declare(strict_types=1);

use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\SmtpOutboundConfig;

final class SmtpOutboundConfigUnitTest extends TestCase
{
    public function test_init_store_values(): void
    {
        // @Arrange
        $one = new SmtpOutboundConfig(
            uid: 'one',
            tenant: new TenantRef('one'),
            host: 'one',
            port: true,
            login: 'one',
            password: 'cyphered://cypher',
            senderName: 'one',
            senderEmail: 'one',
            timeout: 1,
            useTls: true,
            maxRetries: 1,
            retryDelay: 1,
            rateLimit: 1,
            version: 1,
        );

        // @Act
        $other = $one->toAttributes()->build();
        $calculated = SmtpOutboundConfig::calculatedFields();

        // @Assert
        $this->assertEquals([], $calculated);
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getTenant(), $other->getTenant());
        $this->assertTrue($one->isTenantChanged());
        $this->assertEquals($one->getHost(), $other->getHost());
        $this->assertTrue($one->isHostChanged());
        $this->assertEquals($one->isPort(), $other->isPort());
        $this->assertTrue($one->isPortChanged());
        $this->assertEquals($one->getLogin(), $other->getLogin());
        $this->assertTrue($one->isLoginChanged());
        $this->assertEquals($one->getPassword(), $other->getPassword());
        $this->assertTrue($one->isPasswordChanged());
        $this->assertEquals($one->getSenderName(), $other->getSenderName());
        $this->assertTrue($one->isSenderNameChanged());
        $this->assertEquals($one->getSenderEmail(), $other->getSenderEmail());
        $this->assertTrue($one->isSenderEmailChanged());
        $this->assertEquals($one->getTimeout(), $other->getTimeout());
        $this->assertTrue($one->isTimeoutChanged());
        $this->assertEquals($one->isUseTls(), $other->isUseTls());
        $this->assertTrue($one->isUseTlsChanged());
        $this->assertEquals($one->getMaxRetries(), $other->getMaxRetries());
        $this->assertTrue($one->isMaxRetriesChanged());
        $this->assertEquals($one->getRetryDelay(), $other->getRetryDelay());
        $this->assertTrue($one->isRetryDelayChanged());
        $this->assertEquals($one->getRateLimit(), $other->getRateLimit());
        $this->assertTrue($one->isRateLimitChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
    }
    public function test_replace_change_values(): void
    {
        // @Arrange
        $base = new SmtpOutboundConfig(
            uid: 'one',
            tenant: new TenantRef('one'),
            host: 'one',
            port: true,
