            senderEmail: 'one',
            timeout: 1,
            useTls: true,
            maxRetries: 1,
            retryDelay: 1,
            rateLimit: 1,
            version: 1,
        );
        $other = new SmtpOutboundConfig(
            uid: 'other',
            tenant: new TenantRef('other'),
            host: 'other',
            port: false,
            login: 'other',
            password: 'cyphered://ocyphered',
            senderName: 'other',
            senderEmail: 'other',
            timeout: 2,
            useTls: false,
            maxRetries: 2,
            retryDelay: 2,
            rateLimit: 2,
            version: 2,
        );

        // @Act
        $one = $base->replace($other->toAttributes());

        // @Assert
        $this->assertEquals($one->uid(), $base->uid());
        $this->assertEquals($one->getTenant(), $other->getTenant());
        $this->assertTrue($one->isTenantChanged($base));
        $this->assertEquals($one->getHost(), $other->getHost());
        $this->assertTrue($one->isHostChanged($base));
        $this->assertEquals($one->isPort(), $other->isPort());
        $this->assertTrue($one->isPortChanged($base));
        $this->assertEquals($one->getLogin(), $other->getLogin());
        $this->assertTrue($one->isLoginChanged($base));
        $this->assertEquals($one->getPassword(), $other->getPassword());
        $this->assertTrue($one->isPasswordChanged($base));
        $this->assertEquals($one->getSenderName(), $other->getSenderName());
        $this->assertTrue($one->isSenderNameChanged($base));
        $this->assertEquals($one->getSenderEmail(), $other->getSenderEmail());
        $this->assertTrue($one->isSenderEmailChanged($base));
        $this->assertEquals($one->getTimeout(), $other->getTimeout());
        $this->assertTrue($one->isTimeoutChanged($base));
        $this->assertEquals($one->isUseTls(), $other->isUseTls());
        $this->assertTrue($one->isUseTlsChanged($base));
        $this->assertEquals($one->getMaxRetries(), $other->getMaxRetries());
        $this->assertTrue($one->isMaxRetriesChanged($base));
        $this->assertEquals($one->getRetryDelay(), $other->getRetryDelay());
        $this->assertTrue($one->isRetryDelayChanged($base));
        $this->assertEquals($one->getRateLimit(), $other->getRateLimit());
        $this->assertTrue($one->isRateLimitChanged($base));
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged($base));
    }
    public function test_json_compare(): void
    {
        // @Arrange
        $one = new SmtpOutboundConfig(
            uid: 'one',
            tenant: new TenantRef('one'),
            host: 'one',
            port: true,
            login: 'one',
            password: 'cyphered://cypher',
            senderName: 'one',
            senderEmail: 'one',
            timeout: 1,
            useTls: true,
            maxRetries: 1,
            retryDelay: 1,
            rateLimit: 1,
            version: 1,
        );

        // @Act
        $json = $one->asPublicJson();

        // @Assert
        $this->assertEquals('one', $json['uid']);
        $this->assertEquals('one', $json['tenant']['$ref']);
        $this->assertEquals('one', $json['host']);
        $this->assertEquals(true, $json['port']);
        $this->assertEquals('one', $json['login']);
        $this->assertEquals('one', $json['senderName']);
        $this->assertEquals('one', $json['senderEmail']);
        $this->assertEquals(1, $json['timeout']);
        $this->assertEquals(true, $json['useTls']);
        $this->assertEquals(1, $json['maxRetries']);
        $this->assertEquals(1, $json['retryDelay']);
        $this->assertEquals(1, $json['rateLimit']);
        $this->assertEquals(1, $json['version']);
    }
